# Compare fitted fc candidates by the same repeated CV: group-balanced logistic (L2), LDA-style, covariance-aware projection, refit shrunk toward original w
def gweights(idx):
    cnt = np.bincount(g[idx], minlength=4); return (1.0/cnt)[g[idx]]*len(idx)/4
def fit_logreg(C, penalty='l2', balance='group'):
    def f(Xtr, tr):
        mu, sd = Xtr.mean(0), Xtr.std(0)+1e-6
        Z = (Xtr-mu)/sd
        sw = gweights(tr) if balance=='group' else None
        if penalty=='l2': clf = LogisticRegression(C=C, max_iter=3000)
        else: clf = LogisticRegression(C=C, penalty='l1', solver='liblinear', max_iter=500)
        clf.fit(Z, y[tr], sample_weight=sw)
        w = clf.coef_[0]/sd; b = clf.intercept_[0] - w@mu
        return w,b
    return f
def within_cov(Xtr, tr):
    mu = group_means(Xtr, tr); R = Xtr - mu[g[tr]]
    return mu, R.T@R/len(tr)
def fit_lda(lam):
    def f(Xtr, tr):
        mu, S = within_cov(Xtr, tr)
        S = S + lam*np.trace(S)/S.shape[0]*np.eye(S.shape[0])
        dbird = 0.5*((mu[2]-mu[0])+(mu[3]-mu[1]))
        w = np.linalg.solve(S, dbird); b = -w@mu.mean(0)
        return w,b
    return f
def fit_project_cov(lam, alpha=1.0):
    def f(Xtr, tr):
        mu, S = within_cov(Xtr, tr)
        S = S + lam*np.trace(S)/S.shape[0]*np.eye(S.shape[0])
        dpl = 0.5*((mu[1]-mu[0])+(mu[3]-mu[2]))
        v = np.linalg.solve(S, dpl)
        w = w_orig - alpha*(w_orig@dpl)/(v@dpl)*v
        b = b_orig + (w_orig-w)@mu.mean(0)
        return w,b
    return f
